syntax:
**Is-A (Inheritance):**
```c++
class BaseClass {
public:
  // ...
};

class DerivedClass : public BaseClass {
public:
  // ...
};
```
**Has-A (Composition):**
```c++
class ComponentClass {
public:
  // ...
};

class CompositeClass {
private:
  ComponentClass component;
public:
  // ...
};
```
**Practical Usage Notes:** Public inheritance should only be used when the derived class truly *is a* specialized version of the base class.  If the relationship is more about containment or membership, composition is preferred.

code_example:
#include <iostream>
#include <string>
class Quote {
public:
  std::string isbn() const { return bookNo; }
  virtual double net_price(std::size_t n) const { return n * price; }
  Quote(const std::string& book, double p): bookNo(book), price(p) {}
private:
  std::string bookNo;
  double price;
};
class Bulk_quote : public Quote {
public:
  Bulk_quote(const std::string& book, double p, std::size_t qty, double disc):
      Quote(book, p), min_qty(qty), discount(disc) {}
  double net_price(std::size_t) const override;
private:
  std::size_t min_qty = 0;
  double discount = 0.0;
};
double Bulk_quote::net_price(std::size_t cnt) const {
  if (cnt >= min_qty)
    return cnt * price * (1 - discount);
  else
    return cnt * price;
}
int main() {
  Bulk_quote bq("0-201-82470-1", 50, 10, 0.2);
  std::cout << bq.net_price(10) << std::endl;
  return 0;
}
